-- Jalankan di Supabase SQL Editor pada proyek BARU. Tinjau kebijakan sebelum produksi.
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', created_at timestamptz default now());
create table public.user_roles(user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in('admin','buyer','supplier','courier')),created_at timestamptz default now(),primary key(user_id,role));
create table public.role_applications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),requested_role text not null check(requested_role in('supplier','courier')),details text not null,address text not null,latitude double precision not null check(latitude between -90 and 90),longitude double precision not null check(longitude between -180 and 180),status text not null default 'pending' check(status in('pending','approved','rejected')),review_note text,reviewed_by uuid references auth.users(id),created_at timestamptz default now());
create unique index one_pending_application on public.role_applications(user_id,requested_role) where status='pending';
create table public.products(id uuid primary key default gen_random_uuid(),name text not null,description text,category text not null check(category in('pupuk','maggot')),price numeric(14,2) not null check(price>=0),stock integer not null default 0 check(stock>=0),image_url text,is_active boolean not null default false,created_at timestamptz default now());
create table public.pickups(id uuid primary key default gen_random_uuid(),supplier_id uuid not null references auth.users(id),courier_id uuid references auth.users(id),category text not null,estimated_kg numeric(12,2) not null check(estimated_kg>0),actual_kg numeric(12,2) check(actual_kg>=0),address text not null,latitude double precision,longitude double precision,scheduled_at timestamptz,status text not null default 'requested' check(status in('requested','assigned','en_route','collected','received','cancelled')),created_at timestamptz default now());
create table public.processing_batches(id uuid primary key default gen_random_uuid(),input_kg numeric(12,2) not null check(input_kg>=0),output_kg numeric(12,2) check(output_kg>=0),process_type text not null check(process_type in('kompos','maggot')),status text not null default 'started',notes text,created_at timestamptz default now());
create table public.inventory_movements(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id),quantity integer not null,reason text not null,created_at timestamptz default now());
create table public.cart_items(user_id uuid not null references auth.users(id),product_id uuid not null references public.products(id),quantity integer not null check(quantity>0),primary key(user_id,product_id));
create table public.orders(id uuid primary key default gen_random_uuid(),buyer_id uuid not null references auth.users(id),address text not null,latitude double precision,longitude double precision,total numeric(14,2) not null default 0,status text not null default 'pending' check(status in('pending','confirmed','packed','shipped','delivered','cancelled')),created_at timestamptz default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid not null references public.products(id),quantity integer not null check(quantity>0),unit_price numeric(14,2) not null check(unit_price>=0));
create table public.payments(id uuid primary key default gen_random_uuid(),order_id uuid not null unique references public.orders(id),method text not null default 'manual',amount numeric(14,2) not null check(amount>=0),status text not null default 'pending' check(status in('pending','verified','rejected')),created_at timestamptz default now());
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references auth.users(id),event text not null,entity_id uuid,created_at timestamptz default now());
create function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.user_roles where user_id=(select auth.uid()) and role='admin')$$;
create function public.has_role(r text) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.user_roles where user_id=(select auth.uid()) and role=r)$$;
create function public.new_user_profile() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''));insert into public.user_roles(user_id,role) values(new.id,'buyer');return new;end$$;
create trigger on_user_created after insert on auth.users for each row execute function public.new_user_profile();
create function public.review_role_application(app_id uuid,decision text,note text default null) returns void language plpgsql security definer set search_path='' as $$declare a public.role_applications%rowtype;begin if not public.is_admin() then raise exception 'Access denied';end if;if decision not in('approved','rejected') then raise exception 'Invalid decision';end if;select * into a from public.role_applications where id=app_id and status='pending' for update;if not found then raise exception 'Application not pending';end if;update public.role_applications set status=decision,review_note=note,reviewed_by=auth.uid() where id=app_id;if decision='approved' then insert into public.user_roles(user_id,role) values(a.user_id,a.requested_role) on conflict do nothing;end if;insert into public.audit_logs(actor_id,event,entity_id) values(auth.uid(),'role_'||decision,app_id);end$$;
revoke all on function public.review_role_application(uuid,text,text) from public;grant execute on function public.review_role_application(uuid,text,text) to authenticated;
alter table public.profiles enable row level security;alter table public.user_roles enable row level security;alter table public.role_applications enable row level security;alter table public.products enable row level security;alter table public.pickups enable row level security;alter table public.processing_batches enable row level security;alter table public.inventory_movements enable row level security;alter table public.cart_items enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.payments enable row level security;alter table public.audit_logs enable row level security;
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy profile_edit on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy roles_read on public.user_roles for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy applications_read on public.role_applications for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy applications_create on public.role_applications for insert to authenticated with check(user_id=auth.uid() and status='pending' and reviewed_by is null);
create policy products_read on public.products for select to authenticated using(is_active or public.is_admin());
create policy products_admin on public.products for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy pickups_read on public.pickups for select to authenticated using(public.is_admin() or supplier_id=auth.uid() or courier_id=auth.uid());
create policy pickups_create on public.pickups for insert to authenticated with check(supplier_id=auth.uid() and public.has_role('supplier') and status='requested' and courier_id is null);
create policy pickups_admin on public.pickups for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy batches_admin on public.processing_batches for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy inventory_admin on public.inventory_movements for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy cart_owner on public.cart_items for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy orders_read on public.orders for select to authenticated using(buyer_id=auth.uid() or public.is_admin());
create policy orders_admin on public.orders for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy order_items_read on public.order_items for select to authenticated using(public.is_admin() or exists(select 1 from public.orders o where o.id=order_id and o.buyer_id=auth.uid()));
create policy payments_read on public.payments for select to authenticated using(public.is_admin() or exists(select 1 from public.orders o where o.id=order_id and o.buyer_id=auth.uid()));
create policy payments_admin on public.payments for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy audits_admin on public.audit_logs for select to authenticated using(public.is_admin());
-- Checkout, stok, kurir status dan pembayaran harus diimplementasikan melalui transaksi/RPC server yang aman.
-- Tidak ada policy insert order dari client untuk mencegah manipulasi harga dan stok.
